/// Make a mutable pointer opaque to LLVM's interprocedural analysis.
///
/// Prevents LLVM from deducing `captures(none)` and `readnone` on pointer
/// parameters, which causes callers to pass `poison` → ud2 cascade.
/// Zero runtime cost (single mov instruction, register allocator eliminates it).
#[inline(always)]
pub unsafe fn opaque_ptr<T>(ptr: *mut T) -> *mut T {
    let p: *mut T;
    #[cfg(target_arch = "x86")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    #[cfg(target_arch = "x86_64")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    #[cfg(target_arch = "aarch64")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    p
}

/// Make a const pointer opaque to LLVM's interprocedural analysis.
/// Same as `opaque_ptr` but for `*const T` parameters.
#[inline(always)]
pub unsafe fn opaque_ptr_const<T>(ptr: *const T) -> *const T {
    let p: *const T;
    #[cfg(target_arch = "x86")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    #[cfg(target_arch = "x86_64")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    #[cfg(target_arch = "aarch64")]
    core::arch::asm!("mov {0}, {1}", out(reg) p, in(reg) ptr, options(nostack, preserves_flags));
    p
}

// ============================================================================
// Auto-generated DDK bindings (full kernel API surface)
// ============================================================================

mod bindgen_common;

#[cfg(target_arch = "aarch64")]
mod bindgen_arm64;

#[cfg(target_arch = "x86_64")]
mod bindgen_amd64;

#[cfg(target_arch = "x86")]
mod bindgen_i386;

/// Full kernel API — auto-generated bindings with correct calling conventions.
///
/// Provides ~3,300 extern functions covering all internal kernel subsystems
/// (Mi*, Ki*, Obp*, Psp*, Sep*, Cmp*, Iop*, Cc*, Ex*, Ke*, Io*, Mm*, Rtl*,
/// Nt/Zw*, etc.), ~1,850 structs (EPROCESS, ETHREAD, OBJECT_HEADER, MMPTE,
/// MMPFN, MMVAD, TOKEN, HANDLE_TABLE, POOL_HEADER, etc.), and ~4,400 type
/// aliases. Use `ntkrnl_sys::ddk::*` when porting new kernel subsystems —
/// every kernel function is available without hand-writing extern declarations.
///
/// Note: Types here use bindgen naming (`_LIST_ENTRY`, `_KDPC`, etc.) with
/// Windows-style type aliases (`LIST_ENTRY = _LIST_ENTRY`). The hand-written
/// modules above use the alias names directly as struct names.
pub mod ddk {
    pub use super::bindgen_common::*;

    #[cfg(target_arch = "aarch64")]
    pub use super::bindgen_arm64::*;

    #[cfg(target_arch = "x86_64")]
    pub use super::bindgen_amd64::*;

    #[cfg(target_arch = "x86")]
    pub use super::bindgen_i386::*;

    // i386 fat-LTO ud2 workaround: The C shims for KeEnterCriticalRegion and
    // KeLeaveCriticalRegion are eliminated by LTO (replaced with ud2) because
    // C code uses the ke_x.h macros instead. Override with inline Rust versions.
    #[cfg(all(target_arch = "x86", feature = "inline_exports"))]
    pub use super::inline::ke::KeEnterCriticalRegion;
    #[cfg(all(target_arch = "x86", feature = "inline_exports"))]
    pub use super::inline::ke::KeLeaveCriticalRegion;

    // rtltypes.h, x86 only: `#define SLIST_ENTRY SINGLE_LIST_ENTRY` / `#define PSLIST_ENTRY
    // PSINGLE_LIST_ENTRY`. Type aliases spelled as macros, which bindgen drops; the 64-bit
    // arches typedef a real struct. (atapi's completion DPC walks an SLIST through them.)
    #[cfg(target_arch = "x86")]
    pub type SLIST_ENTRY = SINGLE_LIST_ENTRY;
    #[cfg(target_arch = "x86")]
    pub type PSLIST_ENTRY = PSINGLE_LIST_ENTRY;
}

// ============================================================================
// HAL FFI bindings (generated by generate_hal_bindings.sh)
// ============================================================================
//
// arm64 omitted on purpose — the arm64 HAL is C-stub only, uses standard
// NDK types already covered by the kernel bindgen output above. Only x86
// HAL gets a Rust translation per the revised hal-translation-audit.md
// "Strategic update 2026-05-10".

// Gated behind `hal_bindgen` feature (default-on): pre-kernel consumers
// (freeldr-rust) opt out via `default-features = false` to avoid
// rustc emitting raw-dylib import thunks for ntoskrnl.exe statics that
// only exist in kernel-mode (task #33 — NlsMb*/NlsOem* dup vs blrtl).
#[cfg(all(target_arch = "x86_64", feature = "hal_bindgen"))]
mod hal_bindgen_amd64;

#[cfg(all(target_arch = "x86", feature = "hal_bindgen"))]
mod hal_bindgen_i386;

/// HAL-private types + ACPI table layouts.
///
/// Auto-generated bindings covering:
/// - HAL-internal headers: `halhw.h`, `halp.h`, `haldma.h`, `bus.h`,
///   `halacpi.h`, `mps.h`, `halirq.h`, `ioapic.h`.
/// - ACPICA umbrella (`vendor/acpica/include/acpi.h`) with all
///   spec table layouts: FADT, MADT, RSDT, XSDT, SRAT, etc.
///
/// **Use `hal_ddk::*` when porting HAL files.** Types in this module are
/// distinct Rust types from the ones in `ddk::*` even when they correspond
/// to the same C type (e.g. `hal_ddk::LIST_ENTRY` ≠ `ddk::LIST_ENTRY` as
/// Rust types, though their layouts are identical). Cast at the kernel↔HAL
/// boundary as needed; layouts are spec-equivalent.
///
/// arm64 not provided — see top of module for rationale.
#[cfg(all(any(target_arch = "x86_64", target_arch = "x86"), feature = "hal_bindgen"))]
pub mod hal_ddk {
    #[cfg(target_arch = "x86_64")]
    pub use super::hal_bindgen_amd64::*;

    #[cfg(target_arch = "x86")]
    pub use super::hal_bindgen_i386::*;
}

